import {worldPath} from './world-path.js?v=county11';
export function hashSeed(key){let n=2166136261;for(const c of String(key))n=Math.imul(n^c.charCodeAt(0),16777619);return n>>>0;}
export function createAgent(key,x,z,bounds,{radius=.4,speed=1,person=false}={}){const a={key,x,z,heading:0,bounds,radius,speed,person,seed:hashSeed(key)||1,phase:0,mode:'idle',wait:1,route:[],lastMode:null};a.random=()=>{a.seed=(Math.imul(a.seed,1664525)+1013904223)>>>0;return a.seed/4294967296;};a.phase=a.random()*40;a.wait=1+a.random()*8;a.rate=.84+a.random()*.3;return a;}
export function circleClear(x,z,r,blocked){if(blocked(x,z))return false;for(let i=0;i<8;i++)if(blocked(x+Math.cos(i*Math.PI/4)*r,z+Math.sin(i*Math.PI/4)*r))return false;return true;}
export function segmentClear(a,b,r,blocked){const d=Math.hypot(b.x-a.x,b.z-a.z),steps=Math.max(1,Math.ceil(d/.25));for(let i=0;i<=steps;i++)if(!circleClear(a.x+(b.x-a.x)*i/steps,a.z+(b.z-a.z)*i/steps,r,blocked))return false;return true;}
export function giveGoal(a,goal,blocked,mode='walk'){if(goal.x<a.bounds.minX||goal.x>a.bounds.maxX||goal.z<a.bounds.minZ||goal.z>a.bounds.maxZ||!circleClear(goal.x,goal.z,a.radius,blocked))return false;let route;if(segmentClear(a,goal,a.radius,blocked))route=[goal];else route=worldPath(a,goal,{bounds:a.bounds,blocked:(x,z)=>!circleClear(x,z,a.radius,blocked),maxVisits:5000});if(!route.length)return false;a.route=route;a.mode=mode;a.wait=0;return true;}
export function updateAgent(a,dt,blocked,peers=[]){dt=Math.min(.1,Math.max(0,dt));a.phase+=dt*a.rate;let moved=0;if(a.pausedUntil>Date.now())return {moved:0,mode:'idle'};if(a.lookHeading!==undefined&&!a.route.length){const diff=Math.atan2(Math.sin(a.lookHeading-a.heading),Math.cos(a.lookHeading-a.heading));a.heading+=Math.max(-dt*1.2,Math.min(dt*1.2,diff));}
 if(a.route.length){const target=a.route[0],dx=target.x-a.x,dz=target.z-a.z,d=Math.hypot(dx,dz);if(d<.15){a.route.shift();if(!a.route.length){a.mode='idle';a.wait=1+a.random()*3;}return {moved:0,mode:a.mode};}const heading=Math.atan2(dx,dz),diff=Math.atan2(Math.sin(heading-a.heading),Math.cos(heading-a.heading));a.heading+=Math.max(-dt*2.8,Math.min(dt*2.8,diff));const step=Math.min(d,a.speed*a.rate*dt),x=a.x+dx/d*step,z=a.z+dz/d*step,peerBlocked=peers.some(p=>p!==a&&Math.hypot(x-p.x,z-p.z)<a.radius+p.radius+.08);
 if(Math.abs(diff)<.9&&segmentClear(a,{x,z},a.radius,blocked)&&!peerBlocked){a.x=x;a.z=z;moved=step;a.stuck=0;}else{a.stuck=(a.stuck||0)+dt;if(a.stuck>2.5){a.route=[];a.wait=.5+a.random()*2;a.stuck=0;}}return {moved,mode:a.mode};}
 a.wait-=dt;if(a.wait<=0){const choices=a.person?['idle','look','rest','walk','walk','work']:['idle','graze','look','rest','walk','walk'];let mode=choices[Math.floor(a.random()*choices.length)];if(mode===a.lastMode)mode=mode==='walk'?'look':'walk';a.lastMode=mode;
 if(mode==='walk'){for(let i=0;i<12;i++){const goal={x:a.bounds.minX+a.random()*(a.bounds.maxX-a.bounds.minX),z:a.bounds.minZ+a.random()*(a.bounds.maxZ-a.bounds.minZ)};if(giveGoal(a,goal,blocked))break;}}
 else {a.mode=mode;a.wait=(mode==='rest'?9:3)+a.random()*(mode==='rest'?18:8);if(mode==='look')a.lookHeading=a.heading+(a.random()-.5)*1.8;}}
 return {moved,mode:a.mode};
}
